Here's the result of running `cat -n` on /app/src/sql/mod.rs:
     1	//! Implements a SQL execution engine. A SQL statement flows through the engine
     2	//! as follows:
     3	//!
     4	//! 1. The `toySQL` client connects to the server, which creates a new
     5	//!    `sql::execution::Session` in `Server::sql_session`.
     6	//!
     7	//! 2. `toySQL` submits a SQL `SELECT` string, which the server executes via
     8	//!    `Session::execute`.
     9	//!
    10	//! 3. `Session::execute` calls `Parser::parse` to parse the SQL `SELECT` string
    11	//!    into an `ast::Statement::Select` AST (Abstract Syntax Tree). The parser
    12	//!    uses the `Lexer` for initial tokenization.
    13	//!     
    14	//! 4. `Session::execute` obtains a new read-only `sql::engine::Transaction` via
    15	//!    `Session::with_txn`. We'll gloss over the details here.
    16	//!
    17	//! 5. `Session::execute` calls `Plan::build` to construct an execution plan
    18	//!    from the AST via the `Planner`, using the `Transaction`'s
    19	//!    `sql::engine::Catalog` trait to look up table schema information.
    20	//!
    21	//! 6. `Session::execute` calls `Plan::optimize` to optimize the execution plan
    22	//!    via the optimizers in `sql::planner::optimizer`. This e.g. performs
    23	//!    filter pushdown to filter rows during storage scans, uses secondary
    24	//!    indexes where appropriate, and chooses more efficient join types.
    25	//!
    26	//! 7. `Session::execute` calls `Plan::execute` to actually execute the plan,
    27	//!    using the `Transaction` to access the `sql::engine::Engine`.  It uses the
    28	//!    executors in `sql::execution` to recursively execute the
    29	//!    `sql::planner::Node` nodes, which stream and process `sql::types::Row`
    30	//!    vectors via `sql::types::Rows` iterators.
    31	//!
    32	//! 8. At the tip of the execution plan there's typically a `Node::Scan` which
    33	//!    performs full table scans from storage. It is executed by
    34	//!    `sql::execution::source::scan`, which calls `Transaction::scan`.
    35	//!
    36	//! 9. The upper `sql::engine::Raft` engine submits a `Read::Scan` request to
    37	//!    Raft via `Raft::read` and `Raft::execute`. This is submitted through the
    38	//!    crossbeam channel `Raft::tx`, which is routed to the local Raft node in
    39	//!    `Server::raft_route` via `raft::Node::step`.
    40	//!
    41	//! 10. We'll skip Raft details, but see the `raft` module documentation. The
    42	//!     `Read::Scan` request eventually makes its way to the SQL state machine
    43	//!     `sql::engine::raft::State` that's managed by Raft. Since this is a read
    44	//!     request, it is executed only on the leader node, calling `State::read`.
    45	//!
    46	//! 11. `State` wraps the `sql::engine::Local` SQL execution engine that runs
    47	//!     on each node, using local storage. `State::read` calls
    48	//!     `Transaction::scan` using a `Local::Transaction`.
    49	//!
    50	//! 12. The `Local` engine uses a `storage::BitCask` engine for local storage,
    51	//!     with `storage::mvcc` providing transactions. See their documentation
    52	//!     for details.
    53	//!
    54	//! 13. `Transaction::scan` uses `sql::engine::KeyPrefix::Table` to obtain the
    55	//!     key prefix for the scanned table, encoded via `encoding::keycode`. It
    56	//!     scans rows under this prefix by calling `MVCC::scan_prefix`, which in
    57	//!     turn dispatches to `BitCask::scan_prefix`. It returns a row iterator.
    58	//!
    59	//! 14. A row iterator is propagated back up through the stack:
    60	//!     `BitCask` → `MVCC` → `Local` → `State` → `Raft` → `scan` → `Plan::execute`
    61	//!
    62	//! 15. `Plan::execute` collects the results in a `ExecutionResult::Select`,
    63	//!     and returns it to `Session::execute`. It in turns returns it to
    64	//!     `Server::sql_session`, which encodes it and sends it across the wire
    65	//!     to `toySQL`, which displays them to the user.
    66	//!
    67	//! TODO: expand this into a "Life of a SQL statement" document.
    68	
    69	pub mod engine;
    70	pub mod execution;
    71	pub mod parser;
    72	pub mod planner;
    73	pub mod types;
    74	
    75	/// SQL tests are implemented as goldenscripts under src/sql/testscripts.
    76	#[cfg(test)]
    77	mod tests {
    78	    use std::collections::HashMap;
    79	    use std::error::Error;
    80	    use std::fmt::Write as _;
    81	    use std::path::Path;
    82	    use std::result::Result;
    83	
    84	    use crossbeam::channel::Receiver;
    85	    use itertools::Itertools as _;
    86	    use tempfile::TempDir;
    87	    use test_each_file::test_each_path;
    88	
    89	    use super::engine::Catalog as _;
    90	    use super::execution::{Session, StatementResult};
    91	    use super::parser::Parser;
    92	    use super::planner::{OPTIMIZERS, Plan};
    93	    use crate::encoding::format::{self, Formatter as _};
    94	    use crate::sql::engine::{Engine, Local};
    95	    use crate::sql::planner::{Planner, Scope};
    96	    use crate::storage::engine::test as testengine;
    97	    use crate::storage::{self, Engine as _};
    98	
    99	    // Run goldenscript tests in src/sql/testscripts.
   100	    test_each_path! { in "src/sql/testscripts/expressions" as expressions => test_goldenscript_expr }
   101	    test_each_path! { in "src/sql/testscripts/optimizers" as optimizers => test_goldenscript }
   102	    test_each_path! { in "src/sql/testscripts/queries" as queries => test_goldenscript }
   103	    test_each_path! { in "src/sql/testscripts/schema" as schema => test_goldenscript }
   104	    test_each_path! { in "src/sql/testscripts/transactions" as transactions => test_goldenscript }
   105	    test_each_path! { in "src/sql/testscripts/writes" as writes => test_goldenscript }
   106	
   107	    /// Runs SQL goldenscripts.
   108	    fn test_goldenscript(path: &Path) {
   109	        // The runner's Session can't borrow from an Engine in the same struct,
   110	        // so pass an engine reference. Use both BitCask and Memory engines and
   111	        // mirror operations across them. Emit engine operations to op_rx.
   112	        let (op_tx, op_rx) = crossbeam::channel::unbounded();
   113	        let tempdir = TempDir::with_prefix("toydb").expect("tempdir failed");
   114	        let bitcask =
   115	            storage::BitCask::new(tempdir.path().join("bitcask")).expect("bitcask failed");
   116	        let memory = storage::Memory::new();
   117	        let engine =
   118	            Local::new(testengine::Emit::new(testengine::Mirror::new(bitcask, memory), op_tx));
   119	        let mut runner = SQLRunner::new(&engine, op_rx);
   120	
   121	        goldenscript::run(&mut runner, path).expect("goldenscript failed")
   122	    }
   123	
   124	    /// Runs expression goldenscripts.
   125	    fn test_goldenscript_expr(path: &Path) {
   126	        goldenscript::run(&mut ExpressionRunner, path).expect("goldenscript failed")
   127	    }
   128	
   129	    /// The SQL test runner.
   130	    struct SQLRunner<'a> {
   131	        engine: &'a TestEngine,
   132	        sessions: HashMap<String, Session<'a, TestEngine>>,
   133	        op_rx: Receiver<testengine::Operation>,
   134	    }
   135	
   136	    type TestEngine =
   137	        Local<testengine::Emit<testengine::Mirror<storage::BitCask, storage::Memory>>>;
   138	
   139	    impl<'a> SQLRunner<'a> {
   140	        fn new(engine: &'a TestEngine, op_rx: Receiver<testengine::Operation>) -> Self {
   141	            Self { engine, sessions: HashMap::new(), op_rx }
   142	        }
   143	    }
   144	
   145	    impl goldenscript::Runner for SQLRunner<'_> {
   146	        fn run(&mut self, command: &goldenscript::Command) -> Result<String, Box<dyn Error>> {
   147	            let mut output = String::new();
   148	
   149	            // Obtain a session based on the command prefix ("" if none).
   150	            let prefix = command.prefix.clone().unwrap_or_default();
   151	            let session = self.sessions.entry(prefix).or_insert_with(|| self.engine.session());
   152	
   153	            // Handle runner commands.
   154	            match command.name.as_str() {
   155	                // dump
   156	                "dump" => {
   157	                    command.consume_args().reject_rest()?;
   158	                    let mut engine = self.engine.mvcc.engine.lock().expect("mutex failed");
   159	                    let mut iter = engine.scan(..);
   160	                    while let Some((key, value)) = iter.next().transpose()? {
   161	                        let fmtkv = format::MVCC::<format::SQL>::key_value(&key, &value);
   162	                        let rawkv = format::Raw::key_value(&key, &value);
   163	                        writeln!(output, "{fmtkv} [{rawkv}]",)?;
   164	                    }
   165	                    return Ok(output);
   166	                }
   167	
   168	                // schema [TABLE...]
   169	                "schema" => {
   170	                    let mut args = command.consume_args();
   171	                    let tables = args.rest_pos().iter().map(|arg| arg.value.clone()).collect_vec();
   172	                    args.reject_rest()?;
   173	
   174	                    let schemas = if tables.is_empty() {
   175	                        session.with_txn(true, |txn| txn.list_tables())?
   176	                    } else {
   177	                        tables
   178	                            .into_iter()
   179	                            .map(|t| session.with_txn(true, |txn| txn.must_get_table(&t)))
   180	                            .try_collect()?
   181	                    };
   182	                    return Ok(schemas.into_iter().join("\n"));
   183	                }
   184	
   185	                // Otherwise, fall through to SQL execution.
   186	                _ => {}
   187	            }
   188	
   189	            // The entire command is the SQL statement. There are no args.
   190	            if !command.args.is_empty() {
   191	                return Err("SQL statements should be given as a command with no args".into());
   192	            }
   193	            let input = &command.name;
   194	            let mut tags = command.tags.clone();
   195	
   196	            // Output the plan if requested.
   197	            if tags.remove("plan") {
   198	                let ast = Parser::parse(input)?;
   199	                let plan =
   200	                    session.with_txn(true, |txn| Planner::new(txn).build(ast)?.optimize())?;
   201	                writeln!(output, "{plan}")?;
   202	            }
   203	
   204	            // Output plan optimizations if requested.
   205	            if tags.remove("opt") {
   206	                if tags.contains("plan") {
   207	                    return Err("using both plan and opt is redundant".into());
   208	                }
   209	                let ast = Parser::parse(input)?;
   210	                let plan = session.with_txn(true, |txn| Planner::new(txn).build(ast))?;
   211	                let Plan::Select(mut root) = plan else {
   212	                    return Err("can only use opt with SELECT plans".into());
   213	                };
   214	                writeln!(output, "{}", format!("Initial:\n{root}").replace('\n', "\n   "))?;
   215	                for optimizer in OPTIMIZERS.iter() {
   216	                    let prev = root.clone();
   217	                    root = optimizer.optimize(root)?;
   218	                    if root != prev {
   219	                        writeln!(
   220	                            output,
   221	                            "{}",
   222	                            format!("{optimizer:?}:\n{root}").replace('\n', "\n   ")
   223	                        )?;
   224	                    }
   225	                }
   226	            }
   227	
   228	            // Execute the statement.
   229	            let result = session.execute(input)?;
   230	
   231	            // Output engine ops if requested.
   232	            if tags.remove("ops") {
   233	                while let Ok(op) = self.op_rx.try_recv() {
   234	                    match op {
   235	                        testengine::Operation::Delete { key } => {
   236	                            let fmtkey = format::MVCC::<format::SQL>::key(&key);
   237	                            let rawkey = format::Raw::key(&key);
   238	                            writeln!(output, "delete {fmtkey} [{rawkey}]")?;
   239	                        }
   240	                        testengine::Operation::Flush => writeln!(output, "flush")?,
   241	                        testengine::Operation::Set { key, value } => {
   242	                            let fmtkv = format::MVCC::<format::SQL>::key_value(&key, &value);
   243	                            let rawkv = format::Raw::key_value(&key, &value);
   244	                            writeln!(output, "set {fmtkv} [{rawkv}]")?;
   245	                        }
   246	                    }
   247	                }
   248	            }
   249	
   250	            // Output the result if requested. SELECT results are always output.
   251	            match result {
   252	                StatementResult::Select { columns, rows } => {
   253	                    if tags.remove("header") {
   254	                        writeln!(output, "{}", columns.into_iter().join(", "))?;
   255	                    }
   256	                    for row in rows {
   257	                        writeln!(output, "{}", row.into_iter().join(", "))?;
   258	                    }
   259	                }
   260	                result if tags.remove("result") => writeln!(output, "{result:?}")?,
   261	                _ => {}
   262	            }
   263	
   264	            // Reject unknown tags.
   265	            if let Some(tag) = tags.iter().next() {
   266	                return Err(format!("unknown tag {tag}").into());
   267	            }
   268	
   269	            Ok(output)
   270	        }
   271	
   272	        /// Drain unprocessed operations after each command.
   273	        fn end_command(&mut self, _: &goldenscript::Command) -> Result<String, Box<dyn Error>> {
   274	            while self.op_rx.try_recv().is_ok() {}
   275	            Ok(String::new())
   276	        }
   277	    }
   278	
   279	    /// A test runner for expressions. Evaluates expressions to values, and
   280	    /// optionally emits the expression tree.
   281	    struct ExpressionRunner;
   282	
   283	    type Catalog<'a> = <Local<storage::Memory> as Engine<'a>>::Transaction;
   284	
   285	    impl goldenscript::Runner for ExpressionRunner {
   286	        fn run(&mut self, command: &goldenscript::Command) -> Result<String, Box<dyn Error>> {
   287	            let mut output = String::new();
   288	
   289	            // The entire command is the expression to evaluate. There are no args.
   290	            if !command.args.is_empty() {
   291	                return Err("expressions should be given as a command with no args".into());
   292	            }
   293	            let input = &command.name;
   294	            let mut tags = command.tags.clone();
   295	
   296	            // Parse and build the expression.
   297	            let ast = Parser::parse_expr(input)?;
   298	            let expr = Planner::<Catalog>::build_expression(ast, &Scope::new())?;
   299	
   300	            // Evaluate the expression.
   301	            let value = expr.evaluate(None)?;
   302	            write!(output, "{value}")?;
   303	
   304	            // If requested, convert the expression to conjunctive normal form
   305	            // and dump it. Assert that it produces the same result.
   306	            if tags.remove("cnf") {
   307	                let cnf = expr.clone().into_cnf();
   308	                assert_eq!(value, cnf.evaluate(None)?, "CNF result differs");
   309	                write!(output, " ← {cnf}")?;
   310	            }
   311	
   312	            // If requested, debug-dump the parsed expression.
   313	            if tags.remove("expr") {
   314	                write!(output, " ← {:?}", expr)?;
   315	            }
   316	            writeln!(output)?;
   317	
   318	            // Reject unknown tags.
   319	            if let Some(tag) = tags.iter().next() {
   320	                return Err(format!("unknown tag {tag}").into());
   321	            }
   322	
   323	            Ok(output)
   324	        }
   325	    }
   326	}
