                    } else {
                        return Ok(Some(Token::Ident(ident)));
                    }
                }
                Some(c) => ident.push(c),
                None => return errinput!("unterminated quoted identifier"),
            }
        }
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let mut num = String::new();

        // Handle negative numbers - they're separate tokens
        if self.chars.peek() == Some(&'-') {
            return None;
        }

        // Integer part
        while let Some(&c) = self.chars.peek() {
            if c.is_ascii_digit() {
                num.push(c);
                self.chars.next();
            } else {
                break;
            }
        }

        // Decimal part
        if self.next_is('.') {
            num.push('.');
            while let Some(&c) = self.chars.peek() {
                if c.is_ascii_digit() {
                    num.push(c);
                    self.chars.next();
                } else {
                    break;
                }
            }
        }

