        if let Some(&c) = self.chars.peek() {
            if c == 'e' || c == 'E' {
                num.push(c);
                self.chars.next();
                if let Some(&c) = self.chars.peek() {
                    if c == '+' || c == '-' {
                        num.push(c);
                        self.chars.next();
                    }
                }
                while let Some(&c) = self.chars.peek() {
                    if c.is_ascii_digit() {
                        num.push(c);
                        self.chars.next();
                    } else {
                        break;
                    }
                }
            }
        }

        // Check for special values
        if num == "inf" || num == "infinity" {
            return Some(Token::Number("inf".to_string()));
        }
        if num == "nan" {
            return Some(Token::Number("nan".to_string()));
        }

        Some(Token::Number(num))
    }

